with prev_events as (select *, lag(event_time) over (partition by page order by event_time, id) as prev_event_time from web_events), flagged as (select *, case when prev_event_time is null or event_time > prev_event_time + interval 14 days then 1 else 0 end as new_group_flag from prev_events), sessions_web_events as (select *, sum(new_group_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_no from flagged), gaps as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval 7 days then 1 else 0 end as new_group_flag_2 from sessions_web_events), sessionized as (select *, sum(new_group_flag_2) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as burst_id from gaps), enriched as (select *, rank() over (partition by event_type order by burst_id desc) as burst_id_rank, lead(session_no, 1) over (order by burst_id, id) as next_session_no, lag(session_no, 2, 0) over (partition by page order by new_group_flag, id) as prev_session_no, last_value(duration_sec, true) over (partition by event_type order by new_group_flag, id rows between unbounded preceding and current row) as last_known_duration_sec, dense_rank() over (partition by event_type order by burst_id desc) as burst_id_dense_rank from sessionized), joined as (select a.*, s.browser from enriched a inner join sessions s on a.session_id = s.id), flagged_2 as (select *, case when prev_event_time - lag(prev_event_time) over (partition by page order by prev_event_time, id) > interval '30' day then 1 else 0 end as new_group_flag_3 from joined), sessions_web_events_2 as (select *, sum(new_group_flag_3) over (partition by page order by prev_event_time, id rows between unbounded preceding and current row) as session_id_2 from flagged_2), with_gaps as (select *, case when lag(event_time) over (partition by event_type order by event_time, id) is null or event_time > lag(event_time) over (partition by event_type order by event_time, id) + interval 30 days then 1 else 0 end as is_new_session from sessions_web_events_2), sessionized_web_events as (select *, sum(is_new_session) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as island_id from with_gaps) select id, session_id, event_type, page, event_time, duration_sec, new_group_flag, session_no, burst_id from sessionized_web_events order by new_group_flag desc nulls first
